/**
 * `sessionTimeline` 命名空间词典（UI 界面文案，跟随 DSH 设置的语言显示）。
 *
 * zh 是键位与占位符的唯一基准；其余 7 语种（en/ja/es/fr/de/ru/pt）与 DSH
 * 内置语言清单对齐（client-locale 注册表），缺词经 fallback 链回落 en，
 * en 也缺才显示键名。`{name}` 占位符由 LocaleRuntime.translate 在调用点
 * 插值；test/locales.test.mjs 强制 8 语种键位与占位符集合一致。
 *
 * Host API 错误经稳定 `code` + `params` 上抛（src/index.ts fail()），客户端
 * 按 `error.<code>` 键翻译——错误文案因此也跟随语言；`error` 字段保留中文
 * 原文，仅供旧客户端/日志兜底。
 *
 * 命名空间声明放在键集旁：任何引用 `TranslateNS<'sessionTimeline'>` 或
 * `PropsLocale<'sessionTimeline'>` 的模块只需本文件。
 */
import type {} from '@deepseek-ai/dsh-client-ui-slots'

/** 客户端词典命名空间（ctx.locale.bind / slots.register 的 locale 选项）。 */
export const NS = 'sessionTimeline'

